#include "mldsa_native.h"
#if MLD_CONFIG_PARAMETER_SET != 44
#error Stage13C baseline is pinned to ML-DSA-44.
#endif
#define B_KEYPAIR PQCP_MLDSA_NATIVE_MLDSA44_keypair_internal
#define B_SIGN PQCP_MLDSA_NATIVE_MLDSA44_signature_internal
#define B_VERIFY PQCP_MLDSA_NATIVE_MLDSA44_verify_internal
using Clock=std::chrono::steady_clock;using H32=std::array<unsigned char,32>;
static double ms(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::milli>(b-a).count();}
static void os_random(unsigned char*p,size_t n){if(BCryptGenRandom(nullptr,p,(ULONG)n,BCRYPT_USE_SYSTEM_PREFERRED_RNG)!=0)throw std::runtime_error("RNG");}
static uint64_t sm64(uint64_t&x){x+=0x9e3779b97f4a7c15ULL;uint64_t z=x;z=(z^(z>>30))*0xbf58476d1ce4e5b9ULL;z=(z^(z>>27))*0x94d049bb133111ebULL;return z^(z>>31);}static void det(unsigned char*p,size_t n,uint64_t s){for(size_t i=0;i<n;){uint64_t z=sm64(s);for(int j=0;j<8&&i<n;j++,i++)p[i]=(unsigned char)(z>>(8*j));}}
static uint64_t peak(){PROCESS_MEMORY_COUNTERS p{};if(GetProcessMemoryInfo(GetCurrentProcess(),&p,sizeof(p)))return(uint64_t)p.PeakWorkingSetSize;return 0;}
struct Sha{BCRYPT_ALG_HANDLE a=nullptr;DWORD ol=0;Sha(){DWORD cb=0;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)!=0)throw std::runtime_error("sha");if(BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,(PUCHAR)&ol,sizeof(ol),&cb,0)!=0)throw std::runtime_error("sha prop");}~Sha(){if(a)BCryptCloseAlgorithmProvider(a,0);}H32 hash(const unsigned char*p,size_t n){std::vector<unsigned char>o(ol);BCRYPT_HASH_HANDLE h=nullptr;H32 z{};if(BCryptCreateHash(a,&h,o.data(),ol,nullptr,0,0)!=0)throw std::runtime_error("sha create");if(n&&BCryptHashData(h,(PUCHAR)p,(ULONG)n,0)!=0)throw std::runtime_error("sha data");if(BCryptFinishHash(h,z.data(),32,0)!=0)throw std::runtime_error("sha finish");BCryptDestroyHash(h);return z;}H32 hash(const std::vector<unsigned char>&v){return hash(v.data(),v.size());}H32 node(const H32&x,const H32&y){unsigned char b[64];memcpy(b,x.data(),32);memcpy(b+32,y.data(),32);return hash(b,64);}};
struct Key{std::vector<unsigned char>pk,sk;Key():pk(MLDSA_PUBLICKEYBYTES(44)),sk(MLDSA_SECRETKEYBYTES(44)){} };static Key key(uint64_t s){Key k;std::array<unsigned char,MLDSA_SEEDBYTES>d{};det(d.data(),d.size(),s);if(B_KEYPAIR(k.pk.data(),k.sk.data(),d.data())!=0)throw std::runtime_error("key");return k;}static std::vector<unsigned char>signm(const std::vector<unsigned char>&m,const Key&k){std::vector<unsigned char>s(MLDSA_BYTES(44));std::array<unsigned char,MLDSA_RNDBYTES>r{};os_random(r.data(),r.size());const unsigned char pre[2]={0,0};if(B_SIGN(s.data(),m.data(),m.size(),pre,2,r.data(),k.sk.data(),0)!=0)throw std::runtime_error("sign");return s;}static bool verm(const std::vector<unsigned char>&m,const std::vector<unsigned char>&s,const Key&k){const unsigned char pre[2]={0,0};return B_VERIFY(s.data(),m.data(),m.size(),pre,2,k.pk.data(),0)==0;}
static void pu32(std::vector<unsigned char>&v,uint32_t x){for(int i=0;i<4;i++)v.push_back((unsigned char)(x>>(8*i)));}static void pu64(std::vector<unsigned char>&v,uint64_t x){for(int i=0;i<8;i++)v.push_back((unsigned char)(x>>(8*i)));}static void pb(std::vector<unsigned char>&v,const unsigned char*p,size_t n){v.insert(v.end(),p,p+n);}
struct Tree{std::vector<std::vector<H32>>lv;};static Tree tree(Sha&s,const std::vector<H32>&l){Tree t;t.lv.push_back(l);while(t.lv.back().size()>1){auto&c=t.lv.back();std::vector<H32>n(c.size()/2);for(size_t i=0;i<n.size();i++)n[i]=s.node(c[2*i],c[2*i+1]);t.lv.push_back(n);}return t;}static bool path(Sha&s,const Tree&t,int idx,H32 h){int x=idx;for(size_t l=0;l+1<t.lv.size();l++){auto q=t.lv[l][x^1];h=(x&1)?s.node(q,h):s.node(h,q);x>>=1;}return h==t.lv.back()[0];}
static std::vector<unsigned char>leafmsg(const H32&pid,uint64_t period,int aa,int attr,const Key&k,const std::string&base){std::vector<unsigned char>v;pb(v,(const unsigned char*)base.data(),base.size());pb(v,pid.data(),32);pu64(v,period);pu32(v,aa);pu32(v,attr);pb(v,k.pk.data(),k.pk.size());return v;}static std::vector<unsigned char>rootmsg(const H32&r,int aa,int leaves){std::vector<unsigned char>v;const char*d="S13C-BROOT";pb(v,(const unsigned char*)d,strlen(d));pb(v,r.data(),32);pu32(v,aa);pu32(v,leaves);pu64(v,1);return v;}
struct AA{Key k;std::vector<std::vector<unsigned char>>p;std::vector<H32>h;Tree t;std::vector<unsigned char>rm,rs;AA(uint64_t s):k(key(s)){} };
struct Cfg{std::string id,base;int k=0,p=0,authorities=0,leaves=0,warmups=0,trials=0,cold=0;};static std::vector<std::string>split(const std::string&s){std::stringstream q(s);std::string x;std::vector<std::string>a;while(std::getline(q,x,','))a.push_back(x);return a;}static std::vector<Cfg>readm(const std::string&p){std::ifstream f(p);if(!f)throw std::runtime_error("matrix");std::string l;std::getline(f,l);std::vector<Cfg>o;while(std::getline(f,l)){if(l.empty())continue;auto a=split(l);if(a.size()!=9)throw std::runtime_error("row");Cfg c;c.id=a[0];c.base=a[1];c.k=std::stoi(a[2]);c.p=std::stoi(a[3]);c.authorities=std::stoi(a[4]);c.leaves=std::stoi(a[5]);c.warmups=std::stoi(a[6]);c.trials=std::stoi(a[7]);c.cold=std::stoi(a[8]);if(c.k<1||c.k>64||c.p<1||c.p>c.k)throw std::runtime_error("bounds");o.push_back(c);}return o;}
static H32 make_wid(Sha&s,const Cfg&c,const H32&pid,uint64_t period,const std::vector<H32>&roots,const std::vector<Key>&attrs,const Key&periodic){std::vector<unsigned char>v;const char*d="S13C-BASE-MAN";pb(v,(const unsigned char*)d,strlen(d));pb(v,pid.data(),32);pu64(v,period);pu32(v,c.k);pu32(v,c.p);pb(v,(const unsigned char*)c.id.data(),c.id.size());if(c.base=="periodic_mldsa")pb(v,periodic.pk.data(),periodic.pk.size());else for(int i=0;i<c.k;i++)pb(v,attrs[i].pk.data(),attrs[i].pk.size());for(auto&r:roots)pb(v,r.data(),32);return s.hash(v);}
static std::vector<unsigned char>reqmsg(const Cfg&c,uint64_t req,const H32&wid,int attr=-1){std::vector<unsigned char>v;const char*d="S13C-BASE-REQ";pb(v,(const unsigned char*)d,strlen(d));pb(v,wid.data(),32);pb(v,(const unsigned char*)c.id.data(),c.id.size());pu64(v,req);pu32(v,(uint32_t)(attr<0?0xffffffffu:attr));unsigned char n[32];det(n,32,0xA13C0000ULL^req);pb(v,n,32);return v;}
using Registry=std::map<H32,uint64_t>;
struct Prep{double cert=0,merkle=0,total=0;bool ok=false;};static Prep prep_offline(const Cfg&c,Sha&s,const Key&dur,const std::vector<unsigned char>&dm,const std::vector<unsigned char>&ds,const std::vector<AA>&aas){Prep r;auto t0=Clock::now();auto c0=Clock::now();bool ok=verm(dm,ds,dur);for(int aa=0;aa<c.p;aa++)ok=ok&&verm(aas[aa].rm,aas[aa].rs,aas[aa].k);r.cert=ms(c0,Clock::now());double mm=0;for(int i=0;i<c.k;i++){int aa=i%c.p,at=i/c.p;auto q=Clock::now();ok=ok&&path(s,aas[aa].t,at,aas[aa].h[at]);mm+=ms(q,Clock::now());}r.merkle=mm;r.ok=ok;r.total=ms(t0,Clock::now());return r;}
struct On{double sign=0,current=0,verify=0,totalv=0;uint64_t bytes=0;bool ok=false,tamper=false;std::vector<std::vector<unsigned char>>msgs,sigs;};static On online(const Cfg&c,uint64_t req,const H32&wid,Registry&reg,const Key&periodic,const std::vector<Key>&attrs){On r;auto s0=Clock::now();if(c.base=="periodic_mldsa"){r.msgs.push_back(reqmsg(c,req,wid));r.sigs.push_back(signm(r.msgs.back(),periodic));}else for(int i=0;i<c.k;i++){r.msgs.push_back(reqmsg(c,req,wid,i));r.sigs.push_back(signm(r.msgs.back(),attrs[i]));}r.sign=ms(s0,Clock::now());auto v0=Clock::now();auto c0=Clock::now();auto it=reg.find(wid);bool ok=it!=reg.end()&&it->second==1;r.current=ms(c0,Clock::now());auto u0=Clock::now();if(ok){if(c.base=="periodic_mldsa")ok=verm(r.msgs[0],r.sigs[0],periodic);else for(int i=0;i<c.k;i++)ok=ok&&verm(r.msgs[i],r.sigs[i],attrs[i]);}r.verify=ms(u0,Clock::now());r.totalv=ms(v0,Clock::now());r.ok=ok;auto bad=r.sigs[0];bad[0]^=1;r.tamper=c.base=="periodic_mldsa"?!verm(r.msgs[0],bad,periodic):!verm(r.msgs[0],bad,attrs[0]);r.bytes=8+32+(uint64_t)r.sigs.size()*MLDSA_BYTES(44);return r;}
struct Stat{size_t n=0;double mean=0,med=0,sd=0,p95=0,minv=0,maxv=0;};static Stat stats(std::vector<double>v){Stat s;s.n=v.size();if(v.empty())return s;std::sort(v.begin(),v.end());s.minv=v.front();s.maxv=v.back();s.mean=std::accumulate(v.begin(),v.end(),0.0)/v.size();double ss=0;for(auto x:v)ss+=(x-s.mean)*(x-s.mean);s.sd=sqrt(ss/v.size());s.med=v.size()%2?v[v.size()/2]:.5*(v[v.size()/2-1]+v[v.size()/2]);size_t p=(size_t)ceil(.95*v.size());if(p<1)p=1;if(p>v.size())p=v.size();s.p95=v[p-1];return s;}static void emit(std::ofstream&f,const Cfg&c,const char*m,std::vector<double>v){auto s=stats(v);f<<c.id<<","<<c.base<<","<<m<<",ms,"<<s.n<<","<<std::setprecision(12)<<s.mean<<","<<s.med<<","<<s.sd<<","<<s.p95<<","<<s.minv<<","<<s.maxv<<"\n";}
int main(int argc,char**argv){try{std::string matrix="config/stage13c_baseline_matrix.csv",out="results";bool quick=false;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--matrix"&&i+1<argc)matrix=argv[++i];else if(a=="--out"&&i+1<argc)out=argv[++i];else if(a=="--quick")quick=true;}CreateDirectoryA(out.c_str(),nullptr);auto cases=readm(matrix);if(quick&&cases.size()>4){std::vector<Cfg>x{cases[0],cases[1],cases[cases.size()-2],cases.back()};cases=x;}Sha sha;std::ofstream raw(out+"/stage13c_mldsa_online_raw.csv"),cold(out+"/stage13c_mldsa_cold_raw.csv"),sum(out+"/stage13c_mldsa_summary.csv"),val(out+"/STAGE13C_MLDSA_VALIDATION.txt");raw<<"case_id,baseline,k,p,trial,online_sign_ms,current_ms,online_verify_sig_ms,online_verify_total_ms,thin_token_bytes,peak_rss,ok,tamper_rejected\n";cold<<"case_id,baseline,trial,offline_prepare_ms,cold_verify_total_ms,ok\n";sum<<"case_id,baseline,metric,unit,n,mean,median,stddev,p95,min,max\n";bool all=true;int total=0;for(size_t ci=0;ci<cases.size();ci++){Cfg c=cases[ci];if(quick){c.warmups=2;c.trials=3;c.cold=1;}H32 pid{};det(pid.data(),32,0xB130000ULL+ci);uint64_t period=20260816;Key dur=key(0xD130ULL+ci);std::vector<unsigned char>dm(64);det(dm.data(),dm.size(),0xD131ULL+ci);auto ds=signm(dm,dur);Key periodic=key(0x9013ULL+ci);std::vector<Key>attrs;for(int i=0;i<c.k;i++)attrs.push_back(key(0xA130000ULL+ci*128+i));std::vector<AA>aas;for(int aa=0;aa<c.authorities;aa++)aas.emplace_back(0xC130000ULL+ci*128+aa);std::map<std::pair<int,int>,int>ix;for(int i=0;i<c.k;i++)ix[{i%c.p,i/c.p}]=i;for(int aa=0;aa<c.authorities;aa++){aas[aa].p.resize(c.leaves);aas[aa].h.resize(c.leaves);for(int at=0;at<c.leaves;at++){int ki=ix.count({aa,at})?ix[{aa,at}]:0;aas[aa].p[at]=leafmsg(pid,period,aa,at,c.base=="periodic_mldsa"?periodic:attrs[ki],c.base);aas[aa].h[at]=sha.hash(aas[aa].p[at]);}aas[aa].t=tree(sha,aas[aa].h);aas[aa].rm=rootmsg(aas[aa].t.lv.back()[0],aa,c.leaves);aas[aa].rs=signm(aas[aa].rm,aas[aa].k);}std::vector<H32>roots;for(int aa=0;aa<c.p;aa++)roots.push_back(aas[aa].t.lv.back()[0]);H32 wid=make_wid(sha,c,pid,period,roots,attrs,periodic);std::vector<double>off,cv;Registry reg;reg[wid]=1;for(int j=0;j<c.cold;j++){auto p=prep_offline(c,sha,dur,dm,ds,aas);auto q=online(c,8000000ULL+j,wid,reg,periodic,attrs);off.push_back(p.total);cv.push_back(p.total+q.totalv);cold<<c.id<<","<<c.base<<","<<j<<","<<p.total<<","<<p.total+q.totalv<<","<<(p.ok&&q.ok)<<"\n";all=all&&p.ok&&q.ok;}emit(sum,c,"offline_prepare",off);emit(sum,c,"cold_verify_total",cv);for(int w=0;w<c.warmups;w++)(void)online(c,7000000ULL+w,wid,reg,periodic,attrs);std::vector<double>sg,vr,cur;uint64_t bytes=0;bool neg=true;for(int t=0;t<c.trials;t++){auto r=online(c,t,wid,reg,periodic,attrs);all=all&&r.ok&&r.tamper;total++;bytes=r.bytes;raw<<c.id<<","<<c.base<<","<<c.k<<","<<c.p<<","<<t<<","<<r.sign<<","<<r.current<<","<<r.verify<<","<<r.totalv<<","<<r.bytes<<","<<peak()<<","<<r.ok<<","<<r.tamper<<"\n";sg.push_back(r.sign);vr.push_back(r.totalv);cur.push_back(r.current);}auto old=reg[wid];reg[wid]=2;auto rr=online(c,999999,wid,reg,periodic,attrs);neg=neg&&!rr.ok;reg[wid]=old;H32 badwid=wid;badwid[0]^=1;auto rr2=online(c,999998,badwid,reg,periodic,attrs);neg=neg&&!rr2.ok;all=all&&neg;emit(sum,c,"online_sign",sg);emit(sum,c,"online_verify",vr);emit(sum,c,"manifest_current",cur);val<<"case_"<<c.id<<"="<<(neg?"PASS":"FAIL")<<" thin_bytes="<<bytes<<"\n";}val<<"total_online_trials="<<total<<"\ncomparison_scope=prepared_state_deletion_baselines\noverall="<<(all?"PASS":"FAIL")<<"\n";std::cout<<"STAGE13C_MLDSA_OVERALL="<<(all?"PASS":"FAIL")<<"\n";return all?0:20;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 30;}}
